parameters.jsCode:
// Anti-hallucination verification gate for company research facts.
// Every extracted quote is checked as a case-insensitive substring of the raw
// scraped website markdown. Facts failing substring matching are stripped.
const ctx = $('Build Research Context').first().json || {};
const res = $json || {};
const out = res.output || res;

const rawText = String(ctx.research_context || '').toLowerCase().replace(/\s+/g, ' ');
const rawFacts = Array.isArray(out.facts) ? out.facts : [];

const groundedFacts = [];
for (const item of rawFacts) {
  const quoteNorm = String(item.quote || '').toLowerCase().replace(/\s+/g, ' ').trim();
  if (quoteNorm.length >= 8 && rawText.includes(quoteNorm)) {
    groundedFacts.push({
      id: String(item.id || ('f' + (groundedFacts.length + 1))),
      fact: String(item.fact || '').trim(),
      quote: String(item.quote || '').trim(),
    });
  }
}

const totalExtracted = rawFacts.length;
const groundedCount = groundedFacts.length;

let status = 'grounded';
if (groundedCount === 0 || !out.what_they_sell) {
  status = 'failed';
} else if (groundedCount < totalExtracted) {
  status = 'partial';
}

return [{ json: {
  ...ctx,
  what_they_sell: String(out.what_they_sell || ''),
  customer_type: String(out.customer_type || ''),
  recent_signal: String(out.recent_signal || ''),
  icp_fit: Number(out.icp_fit) || 0,
  icp_reason: String(out.icp_reason || ''),
  facts: groundedFacts,
  grounded_fact_count: groundedCount,
  research_status: status,
  research_error: res.error || null,
} }];

// Scan free emails scraped from the website against prospect name patterns.
// Matches first, first.last, firstlast, flast, first_last, and firstl.
// Initializes credits used to 0 before contacting paid enrichment vendors.
const prev = $input.first().json || {};
const first = String(prev.first_name || '').toLowerCase().trim();
const last = String(prev.last_name || '').toLowerCase().trim();
const siteEmails = Array.isArray(prev.website_emails) ? prev.website_emails : [];

const f = first.charAt(0);
const l = last.charAt(0);
const patterns = new Set([
  first,
  first + '.' + last,
  first + last,
  f + last,
  first + '_' + last,
  first + l,
].filter(Boolean));

let candidate = '';
let candidateSource = '';
for (const em of siteEmails) {
  const parts = em.split('@');
  const local = (parts[0] || '').toLowerCase();
  if (patterns.has(local)) {
    candidate = em;
    candidateSource = 'website';
    break;
  }
}
// The person search already returned this contact's address, so verify it
// before paying the finder to look it up again.
if (!candidate && prev.search_email) {
  candidate = prev.search_email;
  candidateSource = 'hunter_search';
}
const searchCredits = Number(prev.person_search_credits) || 0;

return [{ json: {
  ...prev,
  candidate_site_email: candidate,
  has_site_email: Boolean(candidate),
  candidate_source: candidateSource,
  email: '',
  email_status: 'not_found',
  email_source: '',
  providers_tried: [],
  credits_used: searchCredits,
  hunter_credits: searchCredits,
  dropcontact_credits: 0,
  settled: false,
  // A domain that does not resolve has no mailboxes either, so paying a
  // provider to search it is money thrown away.
  dead_domain: /DNS resolution failed|ENOTFOUND|getaddrinfo/i.test(
    String((prev.scrape_homepage_error && (prev.scrape_homepage_error.message || prev.scrape_homepage_error)) || '')),
} }];

// Judge verification results for free website candidate email.
// Hunter costs 0.5 credits per verification check.
// Hunter deprecated result in favour of status, so status is read first.
const check = $json || {};
const state = $('Plan Waterfall').item.json || {};
const settings = $('Table Settings').first().json || {};
const minScore = Number(settings.min_verifier_score) || 80;

const result = String(check.status || check.result || '').toLowerCase();
const score = Number(check.score) || 0;

const isDeliverable = result === 'deliverable' || result === 'valid';
const isAcceptAll = (result === 'accept_all' || result === 'risky') && score >= minScore;
const settled = isDeliverable || isAcceptAll;

const source = state.candidate_source || 'website';
const tried = [...state.providers_tried, source];
const credits = Number(state.credits_used || 0) + 0.5;
const hunterCredits = Number(state.hunter_credits || 0) + 0.5;

let emailStatus = state.email_status;
let finalEmail = state.email;
let emailSource = state.email_source;

if (settled) {
  finalEmail = state.candidate_site_email;
  emailStatus = isDeliverable ? 'verified' : 'accept_all';
  emailSource = source;
}

return [{ json: {
  ...state,
  email: finalEmail,
  email_status: emailStatus,
  email_source: emailSource,
  providers_tried: tried,
  credits_used: credits,
  hunter_credits: hunterCredits,
  settled,
} }];

// Evaluate Hunter finder and verifier outcomes against delivery rules.
// Costs 1.0 credit for email finder lookup, plus 0.5 credit if verified.
// Hunter deprecated result in favour of status, so status is read first.
const check = $json || {};
const finder = $('Hunter Email Finder').item.json || {};
const state = $('Settled After Website').item.json || {};
const settings = $('Table Settings').first().json || {};
const minScore = Number(settings.min_verifier_score) || 80;

const foundEmail = String(finder.email || finder.data?.email || '').trim();
const result = String(check.status || check.result || '').toLowerCase();
const score = Number(check.score) || 0;

const tried = [...state.providers_tried, 'hunter'];
// Hunter bills the finder only when it returns an address (1 credit) and
// the verifier only runs on an address (0.5). A miss or an error is free.
const creditsAdded = !finder.error && foundEmail ? 1.5 : 0;
const hunterCredits = Number(state.hunter_credits || 0) + creditsAdded;
const credits = Number(state.credits_used || 0) + creditsAdded;

const isDeliverable = Boolean(foundEmail) && (result === 'deliverable' || result === 'valid');
const isAcceptAll = Boolean(foundEmail) && (result === 'accept_all' || result === 'risky') && score >= minScore;
const settled = isDeliverable || isAcceptAll;

let emailStatus = state.email_status;
let finalEmail = state.email;
let emailSource = state.email_source;

if (settled) {
  finalEmail = foundEmail;
  emailStatus = isDeliverable ? 'verified' : 'accept_all';
  emailSource = 'hunter';
}

return [{ json: {
  ...state,
  email: finalEmail,
  email_status: emailStatus,
  email_source: emailSource,
  providers_tried: tried,
  credits_used: credits,
  hunter_credits: hunterCredits,
  settled,
} }];

// Evaluate Dropcontact enrichment response and verify with Hunter.
// Dropcontact can return an email string or an array of email objects.
// Hunter deprecated result in favour of status, so status is read first.
const check = $json || {};
const enrich = $('Dropcontact Enrich').item.json || {};
const state = $('Settled After Hunter').item.json || {};
const settings = $('Table Settings').first().json || {};
const minScore = Number(settings.min_verifier_score) || 80;

// Without simplify the node can hand back the raw batch, so unwrap data[0].
const rec = Array.isArray(enrich.data) && enrich.data[0] ? enrich.data[0] : enrich;
let candidate = '';
if (typeof rec.email === 'string') {
  candidate = rec.email.trim();
} else if (Array.isArray(rec.email) && rec.email[0]) {
  candidate = String(rec.email[0].email || '').trim();
}

const result = String(check.status || check.result || '').toLowerCase();
const score = Number(check.score) || 0;

const tried = [...state.providers_tried, 'dropcontact'];
// Dropcontact is pay on success: a credit only when it returns an email,
// and the Hunter check on that email is 0.5 of a Hunter credit.
const creditsAdded = candidate ? 1.5 : 0;
const dropcontactCredits = Number(state.dropcontact_credits || 0) + (candidate ? 1 : 0);
const hunterCredits = Number(state.hunter_credits || 0) + (candidate ? 0.5 : 0);
// A lookup that never finished is a provider failure, not a miss.
const dropcontactError = enrich.error ? String(enrich.error.message || enrich.error) : '';
const credits = Number(state.credits_used || 0) + creditsAdded;

const isDeliverable = Boolean(candidate) && (result === 'deliverable' || result === 'valid');
const isAcceptAll = Boolean(candidate) && (result === 'accept_all' || result === 'risky') && score >= minScore;
const settled = isDeliverable || isAcceptAll;

let emailStatus = state.email_status;
let finalEmail = state.email;
let emailSource = state.email_source;

if (settled) {
  finalEmail = candidate;
  emailStatus = isDeliverable ? 'verified' : 'accept_all';
  emailSource = 'dropcontact';
}

return [{ json: {
  ...state,
  email: finalEmail,
  email_status: emailStatus,
  email_source: emailSource,
  providers_tried: tried,
  credits_used: credits,
  hunter_credits: hunterCredits,
  dropcontact_credits: dropcontactCredits,
  dropcontact_error: dropcontactError,
  settled,
} }];

// Single convergence point for the email waterfall.
// Joins providers tried into an audit trail and flags budget skips.
const state = $input.first().json || {};
const tried = state.providers_tried || [];
const credits = Number(state.credits_used) || 0;

let emailStatus = state.email_status || 'not_found';
// The waterfall only stops short of Dropcontact without an answer when a
// budget gate closed it, so that is the one case worth labelling.
if (state.person_found === false) {
  // The person search came back empty, so there was nobody to look up.
  emailStatus = 'no_person';
} else if (!state.settled && !tried.includes('dropcontact')) {
  emailStatus = state.dead_domain ? 'not_found' : 'skipped_budget';
}

return [{ json: {
  ...state,
  email: state.email || '',
  email_status: emailStatus,
  email_source: state.email_source || '',
  providers_tried: tried.join(' > '),
  credits_used: credits,
} }];

