parameters.jsCode:
// Audit generated opener against anti-hallucination and style requirements.
// Ensures fact citation exists, length is under 45 words, no banned fluff,
// no em dashes, and any numbers present appear verbatim in the cited fact.
const state = $('Worth An Opener').item.json || {};
const res = $json || {};
const out = res.output || res;

const facts = Array.isArray(state.facts) ? state.facts : [];
const openerText = String(out.opener || '').trim();
const factId = String(out.fact_id || '').trim();

const citedFact = facts.find(f => f.id === factId);
const words = openerText ? openerText.split(/\s+/).length : 0;

const BANNED_PATTERNS = [
  /hope this (email|finds)/i,
  /came across/i,
  /congrat/i,
  /love what you/i,
  /impressive/i,
  /natural (fit|opportunity|starting point)/i,
  /\b(we|our team) (can|could|build|help)/i,
  /!/,
  /\u2014/,
];

// The opener is about them. Any four consecutive words lifted from our own
// offer means the model pitched instead of observing, so that is a reject.
const norm = t => String(t || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
const offerWords = norm($('Table Settings').first().json.your_offer);
const openerJoined = ' ' + norm(openerText).join(' ') + ' ';
let echoed = '';
for (let i = 0; i + 4 <= offerWords.length; i++) {
  const gram = offerWords.slice(i, i + 4).join(' ');
  if (openerJoined.includes(' ' + gram + ' ')) { echoed = gram; break; }
}

let rejectedReason = '';

if (!openerText) {
  rejectedReason = 'model returned empty opener';
} else if (!citedFact) {
  rejectedReason = 'cited fact_id ' + factId + ' not found in grounded facts';
} else if (words > 45) {
  rejectedReason = 'opener exceeds 45 words (' + words + ' words)';
} else if (echoed) {
  rejectedReason = 'pitches instead of observing (repeats offer: ' + echoed + ')';
} else {
  for (const pattern of BANNED_PATTERNS) {
    if (pattern.test(openerText)) {
      rejectedReason = 'contained banned pattern (' + pattern.toString() + ')';
      break;
    }
  }
}

if (!rejectedReason && citedFact) {
  const openerNumbers = openerText.match(/\b\d+([.,]\d+)?\b/g) || [];
  const factText = (citedFact.fact + ' ' + citedFact.quote);
  for (const num of openerNumbers) {
    if (!factText.includes(num)) {
      rejectedReason = 'number ' + num + ' not found in cited fact';
      break;
    }
  }
}

const accepted = !rejectedReason;

return [{ json: {
  ...state,
  opener: accepted ? openerText : '',
  opener_fact: accepted ? (citedFact ? citedFact.fact : '') : '',
  opener_status: accepted ? 'written' : ('rejected: ' + rejectedReason),
  opener_error: res.error || null,
} }];

// Assemble final row fields, assign terminal status, and aggregate errors.
// Terminal statuses: enriched, no_email, no_domain, skipped, error.
const item = $input.first().json || {};
const settings = $('Table Settings').first().json || {};

let status = item.status || 'pending';
let error = item.error || '';

const errors = [];
if (item.search_error) errors.push('Firecrawl search: ' + (item.search_error.message || item.search_error));
if (item.scrape_homepage_error) errors.push('Firecrawl: ' + (item.scrape_homepage_error.message || item.scrape_homepage_error));
if (item.research_error) errors.push('Research: ' + (item.research_error.message || item.research_error));
if (item.opener_error) errors.push('Opener: ' + (item.opener_error.message || item.opener_error));
if (item.person_search_error) errors.push('Hunter search: ' + item.person_search_error);
if (item.dropcontact_error) errors.push('Dropcontact: ' + item.dropcontact_error);
if (error) errors.push(error);

const fullError = errors.join('; ');

if (status === 'skipped') {
  // Retain skipped status
} else if (fullError) {
  status = 'error';
} else if (!item.domain) {
  status = 'no_domain';
} else if (item.email_status === 'no_person') {
  status = 'no_person';
} else if (item.email_status === 'verified' || item.email_status === 'accept_all') {
  status = 'enriched';
} else {
  status = 'no_email';
}

let openerStatus = item.opener_status || '';
if (!openerStatus) {
  if (status === 'no_domain') {
    openerStatus = 'skipped: no domain';
  } else if (status === 'no_person') {
    openerStatus = 'skipped: no decision maker found';
  } else if (status === 'no_email') {
    openerStatus = 'skipped: no verified email';
  } else if (item.research_status === 'failed') {
    openerStatus = 'skipped: research failed';
  } else if (Number(item.icp_fit) < Number(settings.min_icp_fit_for_opener)) {
    openerStatus = 'skipped: icp fit ' + (item.icp_fit || 0) + ' below threshold';
  } else {
    openerStatus = 'skipped: not qualified';
  }
}

return [{ json: {
  row_id: String(item.row_id || ''),
  status: status,
  first_name: item.first_name || '',
  last_name: item.last_name || '',
  job_title: item.job_title || '',
  person_source: item.person_source || (item.first_name ? 'input' : ''),
  domain: item.domain || '',
  domain_source: item.domain_source || '',
  what_they_sell: item.what_they_sell || '',
  recent_signal: item.recent_signal || '',
  icp_fit: Number(item.icp_fit) || 0,
  icp_reason: item.icp_reason || '',
  email: item.email || '',
  email_status: item.email_status || 'not_found',
  email_source: item.email_source || '',
  providers_tried: item.providers_tried || '',
  credits_used: Number(item.credits_used) || 0,
  hunter_credits: Number(item.hunter_credits) || Number(item.person_search_credits) || 0,
  dropcontact_credits: Number(item.dropcontact_credits) || 0,
  opener: item.opener || '',
  opener_fact: item.opener_fact || '',
  opener_status: openerStatus,
  error: fullError,
  enriched_at: new Date().toISOString(),
} }];

// Calculate aggregate performance metrics once the batch loop finishes.
// Computes provider hit rates, spend in USD, cost per verified lead, and top fits.
const settings = $('Table Settings').first().json || {};
// Every loop pass is its own run of Finalize Row, so collect them all.
const finalized = [];
for (let r = 0; ; r++) {
  let pass = [];
  try { pass = $('Finalize Row').all(0, r) || []; } catch (e) { break; }
  if (!pass.length) break;
  finalized.push(...pass.map(i => i.json));
}

const total = finalized.length;
const verifiedExact = finalized.filter(r => r.email_status === 'verified').length;
const acceptAll = finalized.filter(r => r.email_status === 'accept_all').length;
const totalVerified = verifiedExact + acceptAll;

const bySource = { website: 0, hunter_search: 0, hunter: 0, dropcontact: 0 };
for (const r of finalized) {
  if (r.email && bySource[r.email_source] !== undefined) {
    bySource[r.email_source]++;
  }
}

const totalCredits = finalized.reduce((acc, r) => acc + (Number(r.credits_used) || 0), 0);
const hunterRate = Number(settings.usd_per_hunter_credit) || 0.0245;
const dropcontactRate = Number(settings.usd_per_dropcontact_credit) || 0.158;

// Each provider is priced on the credits it actually billed.
const hunterCredits = finalized.reduce((a, r) => a + (Number(r.hunter_credits) || 0), 0);
const dropcontactCredits = finalized.reduce((a, r) => a + (Number(r.dropcontact_credits) || 0), 0);
const totalUsd = hunterCredits * hunterRate + dropcontactCredits * dropcontactRate;

const costPerLead = totalVerified > 0 ? (totalUsd / totalVerified).toFixed(2) : '0.00';

const openersWritten = finalized.filter(r => r.opener_status === 'written').length;
const openersRejected = finalized.filter(r => (r.opener_status || '').startsWith('rejected')).length;
const openersSkipped = finalized.filter(r => (r.opener_status || '').startsWith('skipped')).length;

const top3 = [...finalized]
  .sort((a, b) => (Number(b.icp_fit) || 0) - (Number(a.icp_fit) || 0))
  .slice(0, 3)
  .map(r => ({
    company: r.domain || r.row_id,
    fit: r.icp_fit,
    email: r.email || 'none',
    status: r.status,
    opener: r.opener || '',
  }));

return [{ json: {
  total_rows: total,
  verified_emails: totalVerified,
  verified_exact: verifiedExact,
  accept_all_emails: acceptAll,
  hit_rate_website: bySource.website,
  hit_rate_hunter_search: bySource.hunter_search,
  hit_rate_hunter: bySource.hunter,
  hit_rate_dropcontact: bySource.dropcontact,
  credits_spent: totalCredits,
  hunter_credits: hunterCredits,
  dropcontact_credits: dropcontactCredits,
  usd_spent: totalUsd.toFixed(2),
  cost_per_verified_usd: costPerLead,
  openers_written: openersWritten,
  openers_rejected: openersRejected,
  openers_skipped: openersSkipped,
  top_rows: top3,
  report_email: settings.report_email || 'REPORT_EMAIL',
} }];

// Clay starts from a company list and finds who to talk to. This turns
// "the right person at this company" into a named contact: Hunter's domain
// search returns the senior people it knows, ranked here against the role on
// the row (or the target roles in Table Settings). Nobody is invented: no
// match means no person, and the row says so.
const prev = $('Has Person').item.json || {};
const settings = $('Table Settings').first().json || {};
const all = $input.all().map(i => i.json || {});
const failed = all.find(j => j.error);

const people = all.flatMap(j => Array.isArray(j.emails) ? j.emails
  : (Array.isArray(j.data?.emails) ? j.data.emails : ((j.value || j.email) ? [j] : [])))
  .filter(p => p && p.first_name && p.last_name);

const split = s => String(s || '').toLowerCase().split(',').map(t => t.trim()).filter(Boolean);
const wantTitles = split(prev.job_title || settings.target_titles);
const wantDepts = split(settings.target_departments);
// Seniority words say how senior someone is, not what they do, so a shared
// "head" or "director" is not a role match.
const GENERIC = new Set(["head", "chief", "senior", "director", "manager", "lead", "vice", "president", "officer", "global", "principal", "executive", "team", "group"]);
const roleWords = t => t.split(/\s+/).filter(w => w.length > 3 && !GENERIC.has(w));

const scoreOf = p => {
  const title = String(p.position || '').toLowerCase();
  let s = 0;
  if (wantTitles.some(t => title.includes(t))) s += 4;
  else if (wantTitles.some(t => roleWords(t).some(w => title.includes(w)))) s += 2;
  if (wantDepts.includes(String(p.department || '').toLowerCase())) s += 3;
  if (p.seniority === 'executive') s += 2;
  else if (p.seniority === 'senior') s += 1;
  if (p.decision_maker) s += 1;
  return s + (Number(p.confidence) || 0) / 100;
};

// Someone who matches neither the role nor the department is not a guess
// worth paying a verifier for.
// When the row names a role, only that role will do: swapping in whoever
// is most senior would hand sales a contact they never asked for.
const titleOf = p => String(p.position || '').toLowerCase();
const roleAsked = Boolean(String(prev.job_title || '').trim());
const pool = roleAsked
  ? people.filter(p => wantTitles.some(t => titleOf(p).includes(t)
      || roleWords(t).some(w => titleOf(p).includes(w))))
  : people;
const ranked = pool.map(p => ({ p, s: scoreOf(p) })).sort((a, b) => b.s - a.s);
const best = ranked.length && ranked[0].s >= 2 ? ranked[0].p : null;

const domain = String(prev.domain || '').toLowerCase();
const email = best ? String(best.value || best.email || '').toLowerCase() : '';

return [{ json: {
  ...prev,
  first_name: best ? best.first_name : '',
  last_name: best ? best.last_name : '',
  job_title: best ? (best.position || prev.job_title || '') : (prev.job_title || ''),
  person_source: best ? 'hunter_search' : '',
  person_found: Boolean(best),
  // Only an address on the company's own domain is worth verifying.
  search_email: email.endsWith('@' + domain) ? email : '',
  // 1 credit per 1 to 10 addresses returned; an empty result is free.
  person_search_credits: people.length ? Math.ceil(people.length / 10) : 0,
  person_search_error: failed ? String(failed.error.message || failed.error) : '',
} }];
